{
  "requirements": [
    {
      "target_id": "t0",
      "policy_source_id": "q17",
      "policy_quote": "At the beginning of the conversation, you have to authenticate the user identity by locating their user id via email, or via name + zip code. This has to be done even when the user already provides the user id.",
      "requirement": "The assistant must authenticate the user identity before proceeding with any action."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q17",
      "policy_quote": "You can only help one user per conversation (but you can handle multiple requests from the same user), and must deny any requests for tasks related to any other user.",
      "requirement": "The assistant must ensure that all actions are taken on behalf of the authenticated user only."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q17",
      "policy_quote": "Before taking any action that updates the database (cancel, modify, return, exchange), you must list the action details and obtain explicit user confirmation (yes) to proceed.",
      "requirement": "The assistant must list the action details (e.g., item changes, payment method) and obtain explicit user confirmation before proceeding with the modification."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q17",
      "policy_quote": "You should not make up any information or knowledge or procedures not provided by the user or the tools, or give subjective recommendations or comments.",
      "requirement": "The assistant must only provide information or actions based on verified data from the user or tools."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q18",
      "policy_quote": "An order can only be modified if its status is 'pending', and you should check its status before taking the action.",
      "requirement": "The assistant must verify that the order status is 'pending' before attempting to modify it."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q18",
      "policy_quote": "For a pending order, each item can be modified to an available new item of the same product but of different product option. There cannot be any change of product types, e.g., modify shirt to shoe.",
      "requirement": "The assistant must ensure that the new item is of the same product type but with different options (e.g., backpack to backpack with different size/material)."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q18",
      "policy_quote": "The user must provide a payment method to pay or receive refund of the price difference. If the user provides a gift card, it must have enough balance to cover the price difference.",
      "requirement": "The assistant must ensure the user provides a valid payment method (e.g., PayPal) for any price difference, and if a gift card is used, it must have sufficient balance."
    },
    {
      "target_id": "t1",
      "policy_source_id": "q17",
      "policy_quote": "You should not make up any information or knowledge or procedures not provided by the user or the tools, or give subjective recommendations or comments.",
      "requirement": "The assistant must ensure that the `modify_pending_order_items` tool call includes accurate and verified item IDs and payment method details."
    },
    {
      "target_id": "t1",
      "policy_source_id": "q18",
      "policy_quote": "Exchange or modify order tools can only be called once per order. Be sure that all items to be changed are collected into a list before making the tool call!!!",
      "requirement": "The assistant must ensure that the `modify_pending_order_items` tool call is made only once per order and includes all items to be modified in the correct format."
    },
    {
      "target_id": "t1",
      "policy_source_id": "q18",
      "policy_quote": "For a pending order, each item can be modified to an available new item of the same product but of different product option. There cannot be any change of product types, e.g., modify shirt to shoe.",
      "requirement": "The assistant must ensure that the `new_item_ids` in the tool call correspond to the same product type as the `item_ids` being modified."
    },
    {
      "target_id": "t1",
      "policy_source_id": "q18",
      "policy_quote": "The user must provide a payment method to pay or receive refund of the price difference. If the user provides a gift card, it must have enough balance to cover the price difference.",
      "requirement": "The assistant must ensure that the `payment_method_id` in the tool call is valid and aligns with the user's provided payment method for price differences."
    },
    {
      "target_id": "t1",
      "policy_source_id": "q16",
      "policy_quote": "You should at most make one tool call at a time, and if you take a tool call, you should not respond to the user at the same time.",
      "requirement": "The assistant must not send a message to the user while making the `modify_pending_order_items` tool call."
    }
  ]
}
